USE [master]
GO

/*******************************************************************************
   Drop database if it exists
********************************************************************************/
IF EXISTS (SELECT name FROM master.dbo.sysdatabases WHERE name = N'PE_DBI202_Su2026_paper7')
BEGIN
	ALTER DATABASE PE_DBI202_Su2026_paper7 SET OFFLINE WITH ROLLBACK IMMEDIATE;
	ALTER DATABASE PE_DBI202_Su2026_paper7 SET ONLINE;
	DROP DATABASE PE_DBI202_Su2026_paper7;
END

GO

CREATE DATABASE PE_DBI202_Su2026_paper7
GO

USE PE_DBI202_Su2026_paper7
GO

/*******************************************************************************
	Drop tables if exists
*******************************************************************************/
DECLARE @sql nvarchar(MAX) 
SET @sql = N'' 

SELECT @sql = @sql + N'ALTER TABLE ' + QUOTENAME(KCU1.TABLE_SCHEMA) 
    + N'.' + QUOTENAME(KCU1.TABLE_NAME) 
    + N' DROP CONSTRAINT ' -- + QUOTENAME(rc.CONSTRAINT_SCHEMA)  + N'.'  -- not in MS-SQL
    + QUOTENAME(rc.CONSTRAINT_NAME) + N'; ' + CHAR(13) + CHAR(10) 
FROM INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS AS RC 

INNER JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE AS KCU1 
    ON KCU1.CONSTRAINT_CATALOG = RC.CONSTRAINT_CATALOG  
    AND KCU1.CONSTRAINT_SCHEMA = RC.CONSTRAINT_SCHEMA 
    AND KCU1.CONSTRAINT_NAME = RC.CONSTRAINT_NAME 

EXECUTE(@sql) 

GO
DECLARE @sql2 NVARCHAR(max)=''

SELECT @sql2 += ' Drop table ' + QUOTENAME(TABLE_SCHEMA) + '.'+ QUOTENAME(TABLE_NAME) + '; '
FROM   INFORMATION_SCHEMA.TABLES
WHERE  TABLE_TYPE = 'BASE TABLE'

Exec Sp_executesql @sql2 
GO 

-- ============================================================
-- 1. RoomType
-- ============================================================
CREATE TABLE RoomType (
    RoomTypeID   INT           IDENTITY(1,1) PRIMARY KEY,
    TypeName     VARCHAR(50)   NOT NULL UNIQUE,
    Description  VARCHAR(255)  NULL,
    BasePrice    DECIMAL(10,2) NOT NULL CHECK (BasePrice > 0),
    MaxOccupancy TINYINT       NOT NULL CHECK (MaxOccupancy BETWEEN 1 AND 10)
);
GO

-- ============================================================
-- 2. Room
-- ============================================================
CREATE TABLE Room (
    RoomID     INT         IDENTITY(1,1) PRIMARY KEY,
    RoomNumber VARCHAR(10) NOT NULL UNIQUE,
    RoomTypeID INT         NOT NULL,
    Floor      TINYINT     NOT NULL CHECK (Floor >= 1),
    Status     VARCHAR(20) NOT NULL DEFAULT 'Available'
                           CHECK (Status IN ('Available','Occupied','Maintenance','Reserved')),
    CONSTRAINT FK_Room_RoomType FOREIGN KEY (RoomTypeID) REFERENCES RoomType(RoomTypeID)
);
GO

-- ============================================================
-- 3. Guest
-- ============================================================
CREATE TABLE Guest (
    GuestID     INT           IDENTITY(1,1) PRIMARY KEY,
    FirstName   VARCHAR(50)   NOT NULL,
    LastName    VARCHAR(50)   NOT NULL,
    Email       VARCHAR(100)  NOT NULL UNIQUE,
    Phone       VARCHAR(20)   NULL,
    NationalID  VARCHAR(30)   NULL UNIQUE,
    Nationality VARCHAR(50)   NULL,
    DateOfBirth DATE          NULL,
    CreatedAt   DATETIME      NOT NULL DEFAULT GETDATE()
);
GO

-- ============================================================
-- 4. Booking
-- ============================================================
CREATE TABLE Booking (
    BookingID    INT           IDENTITY(1,1) PRIMARY KEY,
    GuestID      INT           NOT NULL,
    BookingDate  DATETIME      NOT NULL DEFAULT GETDATE(),
    CheckInDate  DATE          NOT NULL,
    CheckOutDate DATE          NOT NULL,
    Status       VARCHAR(20)   NOT NULL DEFAULT 'Confirmed'
                               CHECK (Status IN ('Confirmed','Checked-In','Checked-Out','Cancelled','No-Show')),
    TotalAmount  DECIMAL(10,2) NOT NULL DEFAULT 0,
	PaymentDate [datetime] NULL DEFAULT GETDATE(),
	PaymentMethod [varchar](30) NULL CHECK (PaymentMethod IN ('Cash','Credit Card','Debit Card','Bank Transfer','Online')),
	PaymentStatus [varchar](20) NULL DEFAULT 'Completed'
                                CHECK (PaymentStatus IN ('Completed','Pending','Refunded','Failed')),
    Notes        VARCHAR(500)  NULL,
    CONSTRAINT FK_Booking_Guest FOREIGN KEY (GuestID) REFERENCES Guest(GuestID),
    CONSTRAINT CK_Booking_Dates CHECK (CheckOutDate > CheckInDate)
);
GO

-- ============================================================
-- 5. BookingDetail  (1-3 rooms per booking)
-- ============================================================
CREATE TABLE BookingDetail (
    DetailID      INT           IDENTITY(1,1) PRIMARY KEY,
    BookingID     INT           NOT NULL,
    RoomID        INT           NOT NULL,
    PricePerNight DECIMAL(10,2) NOT NULL CHECK (PricePerNight > 0),
    NumNights     SMALLINT      NOT NULL CHECK (NumNights > 0),
    SubTotal      AS (PricePerNight * NumNights) PERSISTED,
    CONSTRAINT FK_Detail_Booking     FOREIGN KEY (BookingID) REFERENCES Booking(BookingID),
    CONSTRAINT FK_Detail_Room        FOREIGN KEY (RoomID)    REFERENCES Room(RoomID),
    CONSTRAINT UQ_Detail_BookingRoom UNIQUE (BookingID, RoomID)
);
GO

-- ============================================================
-- 6. BookingGuest  (1-4 occupants per BookingDetail)
-- ============================================================
CREATE TABLE BookingGuest (
    BookingGuestID  INT          IDENTITY(1,1) PRIMARY KEY,
    DetailID        INT          NOT NULL,
    GuestID         INT          NOT NULL,
    IsPrimaryGuest  BIT          NOT NULL DEFAULT 0,
    CONSTRAINT FK_BG_Detail      FOREIGN KEY (DetailID) REFERENCES BookingDetail(DetailID),
    CONSTRAINT FK_BG_Guest       FOREIGN KEY (GuestID)  REFERENCES Guest(GuestID),
    CONSTRAINT UQ_BG_DetailGuest UNIQUE (DetailID, GuestID)
);
GO

-- ============================================================
-- 7. Service
-- ============================================================
CREATE TABLE Service (
    ServiceID   INT           IDENTITY(1,1) PRIMARY KEY,
    ServiceName VARCHAR(100)  NOT NULL UNIQUE,
    Category    VARCHAR(50)   NOT NULL,
    UnitPrice   DECIMAL(10,2) NOT NULL CHECK (UnitPrice >= 0),
    Unit        VARCHAR(30)   NOT NULL DEFAULT 'per use'
);
GO

-- ============================================================
-- 8. BookingService  (0-4 services per booking)
-- ============================================================
CREATE TABLE BookingService (
    BookingServiceID INT      IDENTITY(1,1) PRIMARY KEY,
    BookingID        INT      NOT NULL,
    ServiceID        INT      NOT NULL,
    Quantity         SMALLINT NOT NULL DEFAULT 1 CHECK (Quantity > 0),
    ServiceDate      DATE     NOT NULL DEFAULT CAST(GETDATE() AS DATE),
    TotalCost        DECIMAL(10,2) NULL,
    CONSTRAINT FK_BookSvc_Booking FOREIGN KEY (BookingID) REFERENCES Booking(BookingID),
    CONSTRAINT FK_BookSvc_Service FOREIGN KEY (ServiceID) REFERENCES Service(ServiceID)
);
GO

